function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	changeLookupReadonly(f, 'ma_dvcs');
	var o = f.getItem('ky1');
	if (!f.getItemValue('ky2')) {
		o.value = f.getItem('ky2').value = (new Date()).getMonth() + 1;
		f.getItem('nam').value = (new Date()).getFullYear();
	}
	f.live(o);
}
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, v = f.getItem('mau_bc').value, mForm = f.getItem('ky1').value, mTo = f.getItem('ky2').value, y = f.getItem('nam').value, x = f.getItemValue('chon_tt'), a = 'ky1, ky2, nam, ma_dvcs, mau_bc'.split(',');
			g._$k = [];
			g._alterTitle = [null, [['%m1', mForm, true], ['%m2', mTo, true], ['%y', y, true]]];
			g._hiddenFields = [{Fields: 'ds_nt, thue_nt', Value: (v == '10')},{Fields: 'ds, thue', Value: (v == '20')}];
			g._hiddenForms = [
				{Form: [1, 2, 3, 5, 6, 7, 10, 11, 12, 14, 15, 16], Value: (x == '1')},
				{Form: [0, 2, 3, 4, 6, 7, 9, 11, 12, 13, 15, 16], Value: (x == '2')},
				{Form: [0, 1, 3, 4, 5, 7, 9, 10, 12, 13, 14, 16], Value: (x == '3' || x == '4')},
				{Form: [0, 1, 2, 4, 5, 6, 9, 10, 11, 13, 14, 15], Value: (x == '5'}];

			for (var i = 0; i < a.length; i++) {Array.add(g._$k, [f.getItemValue($func.trim(a[i]))]);}
			remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}
function initForm(f) {
	var o = f.getItem('form'), value = f._itemValue.split(String.fromCharCode(255)), text = f._itemText.split(String.fromCharCode(255));
	for (var i = 0; i < value.length; i++) {
		o.options[i] = new Option(text[i], value[i]);
	}
	var l = f.getItem('chon_tt').options.length;
	if (l > 1 && o.options.length >= l) o.options[l - 1].selected = true;
}
